/// <summary>
/// This class is currently undocumented!
/// </summary>
class AVAListZ5AMark extends RunBase
{
    QueryRun            qListZ5A;
    AVAListZ5AData     listZ5AData;
    AVAListZ5AStatus   listStatus;

    #DEFINE.CurrentVersion(1)
    #LOCALMACRO.CurrentList
        listStatus
    #ENDMACRO

}

