/// <summary>
///    Returns a class that contains the methods that are described by the <c>RunBaseDialogable</c>
///    interface.
/// </summary>
/// <returns>
///    A class that contains the methods that are described by the <c>RunBaseDialogable</c> interface.
/// </returns>
/// <remarks>
///    A dialog can be either built by using the <c>Dialog</c> class or by using a class that is created
///    in the Application Object Tree (AOT).
/// </remarks>
Object dialog()
{
    DialogRunbase dialog = super();

    return dialog;
}

/// <summary>
/// AVAZ5A
/// </summary>
/// <returns>boolean</returns>
public boolean init()
{
    str             statusValue;
    QueryBuildRange queryBuildRange;
    boolean         ret = super();

    switch(listStatus)
    {
        case AVAListZ5AStatus::New:
            statusValue = queryValue(AVAListZ5AStatus::Reported);
            break;
        case AVAListZ5AStatus::Reported:
            statusValue = queryValue(AVAListZ5AStatus::New);
            break;
    }

    queryBuildRange = SysQuery::findOrCreateRange(qListZ5A.query().dataSourceTable(tableNum(AVAListZ5AData)), fieldnum(AVAListZ5AData, Status));
    queryBuildRange.value(statusValue);

    return ret;
}

/// <summary>
/// This method is currently undocumented!
/// </summary>
protected void new()
{
    super();

    qListZ5A   = new QueryRun(querystr(AVAListZ5A));

    qListZ5A.query().dataSourceTable(tableNum(AVAListZ5AData)).addRange(fieldnum(AVAListZ5AData, DispatchId));
}

/// <summary>
/// AVAZ5A
/// </summary>
/// <returns>Container</returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList, qListZ5A.pack()];
}

/// <summary>
/// AVAZ5A
/// </summary>
/// <param name = "_listStatus">AVAListZ5AStatus</param>
/// <returns>AVAListZ5AStatus</returns>
AVAListZ5AStatus parmListStatus(AVAListZ5AStatus _listStatus = listStatus)
{
    listStatus = _listStatus;

    return listStatus;
}

/// <summary>
///    Retrieves the instance of the <c>QueryRun</c> class, which is used by the <c>queryPrompt</c> method.
/// </summary>
/// <returns>
///    The instance of the <c>QueryRun</c> class, which is used by the <c>queryPrompt</c> method.
/// </returns>
/// <remarks>
///    This method is used if a query prompt is the dialog, and if a Select menu item is added to a
///    dialog. Do not create the instance of the <c>QueryRun</c> class when this method is called. Do it
///    in the <c>unpack</c> method and the <c>initParmDefault</c> method, or in the <c>init</c> method.
/// </remarks>
QueryRun queryRun()
{
    return  qListZ5A;
}

/// <summary>
///    Contains the code that does the actual job of the class.
/// </summary>
void run()
{
    ttsbegin;
    while (qListZ5A.next())
    {
        listZ5AData = qListZ5A.get(tablenum(AVAListZ5AData));
        listZ5AData.selectForUpdate(true);
        switch(listStatus)
        {
            case AVAListZ5AStatus::New:
                listZ5AData.status = AVAListZ5AStatus::New;
                break;
            case AVAListZ5AStatus::Reported:
                listZ5AData.status = AVAListZ5AStatus::Reported;
                break;
        }

        listZ5AData.update();
    }
    ttscommit;
}

/// <summary>
/// AVAZ5A
/// </summary>
/// <returns>boolean</returns>
public boolean showQueryValues()
{
    return true;
}

/// <summary>
/// AVAZ5A
/// </summary>
/// <param name = "packedClass">container</param>
/// <returns>boolean</returns>
boolean unpack(container packedClass)
{
    Integer          version         = conpeek(packedClass,1);
    container       packedQuery;

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList,packedQuery]      = packedClass;
            if (packedQuery)
            {
                qListZ5A   = new QueryRun(packedQuery);
            }
            break;
        default:
            return false;
    }

    return true;
}

/// <summary>
/// AVAZ5A
/// </summary>
/// <param name = "args">args</param>
static void main(Args args)
{
    AVAListZ5AMark   listMark;
    FormDataSource    listZ5AMark_ds;

    listZ5AMark_ds   = FormDataUtil::getFormDataSource(args.record());
    listMark         = new AVAListZ5AMark();
    listMark.parmListStatus(args.parmEnum());
    listMark.init();

    if (listMark.prompt())
    {
        //listMark.run();
        listMark.runOperation();
    }

    //listZ5AMark_ds.executeQuery();
}
